parameters.jsCode:
const body = $input.item.json.body ?? $input.item.json;
const required = ['repo', 'branch', 'job_id', 'log_path'];
for (const key of required) {
  if (!body[key]) {
    throw new Error(`Missing required field in CI webhook payload: ${key}`);
  }
}
return [{
  json: {
    repo: body.repo,
    branch: body.branch,
    job_id: body.job_id,
    log_path: body.log_path,
    received_at: new Date().toISOString()
  }
}];

const fs = require('fs');
const item = $input.item.json;
const logContent = fs.readFileSync(item.log_path, 'utf8');
const knownIssues = fs.readFileSync('/data/known-issues.md', 'utf8');
return [{
  json: {
    ...item,
    log_content: logContent,
    known_issues_content: knownIssues
  }
}];

